import SwiftUI

public struct FLXToggleStyle: ToggleStyle {
    public init() {}

    public func makeBody(configuration: Configuration) -> some View {
        FLXToggleStyleBody(configuration: configuration)
    }
}

struct AnyFLXToggleStyle: ToggleStyle {
    private let _makeBody: (Configuration) -> AnyView

    init<S: ToggleStyle>(_ style: S) {
        _makeBody = { AnyView(style.makeBody(configuration: $0)) }
    }

    func makeBody(configuration: Configuration) -> some View {
        _makeBody(configuration)
    }
}

private struct FLXToggleStyleOverrideKey: EnvironmentKey {
    static let defaultValue: AnyFLXToggleStyle? = nil
}

extension EnvironmentValues {
    var flxToggleStyleOverride: AnyFLXToggleStyle? {
        get { self[FLXToggleStyleOverrideKey.self] }
        set { self[FLXToggleStyleOverrideKey.self] = newValue }
    }
}

extension View {
    public func flxToggleStyle<S: ToggleStyle>(_ style: S) -> some View {
        environment(\.flxToggleStyleOverride, AnyFLXToggleStyle(style))
    }
}

#if os(macOS)
import SwiftUI

struct FLXToggleStyleBody: View {
    @Environment(\.flxTheme) private var theme
    @Environment(\.isEnabled) private var isEnabled
    @Environment(\.controlSize) private var controlSize

    let configuration: FLXToggleStyle.Configuration

    var body: some View {
        Button {
            configuration.isOn.toggle()
        } label: {
            HStack(spacing: FLXToggleMetrics.labelSpacing(controlSize)) {
                box
                configuration.label
                    .flxFont(FLXTypography.control(controlSize))
                    .foregroundStyle(theme.colors.foreground)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .opacity(isEnabled ? 1 : FLXOpacity.disabled)
    }

    private var box: some View {
        let side = FLXToggleMetrics.boxSize(controlSize)
        return RoundedRectangle(cornerRadius: FLXToggleMetrics.cornerRadius)
            .fill(configuration.isOn ? theme.colors.primary : theme.colors.card)
            .overlay(
                RoundedRectangle(cornerRadius: FLXToggleMetrics.cornerRadius)
                    .strokeBorder(configuration.isOn ? theme.colors.primary : theme.colors.input, lineWidth: FLXBorderWidth.thin)
            )
            .overlay {
                if configuration.isOn {
                    Image(systemName: "checkmark")
                        .font(.system(size: side * FLXToggleMetrics.checkmarkScale, weight: .bold))
                        .foregroundStyle(theme.colors.primaryForeground)
                }
            }
            .frame(width: side, height: side)
    }
}

private enum FLXToggleMetrics {
    static let cornerRadius: CGFloat = 4
    static let checkmarkScale: CGFloat = 0.6

    static func boxSize(_ controlSize: ControlSize) -> CGFloat {
        switch controlSize {
        case .mini: 12
        case .small: 14
        case .regular: 16
        case .large, .extraLarge: 18
        @unknown default: 16
        }
    }

    static func labelSpacing(_ controlSize: ControlSize) -> CGFloat {
        switch controlSize {
        case .mini, .small: 4
        case .regular, .large, .extraLarge: 5
        @unknown default: 5
        }
    }
}
#endif

import SwiftUI

/// Always controlled — mirrors `FLXTextField`'s `text: Binding<String>`. The on/off
/// value is application data the caller needs to read regardless, so there's no
/// uncontrolled variant (unlike `FLXCollapsible`'s ephemeral open/closed state).
public struct FLXToggle<Label: View>: View {
    @Environment(\.flxToggleStyleOverride) private var styleOverride

    @Binding private var isOn: Bool
    private let label: () -> Label

    public init(isOn: Binding<Bool>, @ViewBuilder label: @escaping () -> Label) {
        self._isOn = isOn
        self.label = label
    }

    public var body: some View {
        Toggle(isOn: $isOn, label: label)
            .toggleStyle(styleOverride ?? AnyFLXToggleStyle(FLXToggleStyle()))
    }
}

extension FLXToggle where Label == Text {
    public init(_ titleKey: LocalizedStringKey, isOn: Binding<Bool>) {
        self.init(isOn: isOn) {
            Text(titleKey)
        }
    }

    @_disfavoredOverload
    public init(_ titleResource: LocalizedStringResource, isOn: Binding<Bool>) {
        self.init(isOn: isOn) {
            Text(titleResource)
        }
    }

    @_disfavoredOverload
    public init<S: StringProtocol>(_ title: S, isOn: Binding<Bool>) {
        self.init(isOn: isOn) {
            Text(title)
        }
    }
}
